request.body:
{{- $scaling := dict "minReplica" (index .flag "min-replica") "maxReplica" (index .flag "max-replica") -}}
{{- if eq (index .flag "min-replica") 0 }}{{ $_ := set $scaling "scaleToZeroTimeout" (index .flag "scale-to-zero-timeout") }}{{ end -}}
{{- $compute := dict "accelerator" .flag.accelerator "instanceType" (index .flag "instance-type") "instanceSize" (index .flag "instance-size") "scaling" $scaling -}}
{{- $model := dict "repository" .flag.repository "framework" .flag.framework "image" (mustFromJson .flag.image) -}}
{{- with .flag.revision }}{{ $_ := set $model "revision" . }}{{ end -}}
{{- with .flag.task }}{{ $_ := set $model "task" . }}{{ end -}}
{{- $body := dict "name" .arg.name "type" .flag.type "provider" (dict "vendor" .flag.vendor "region" .flag.region) "compute" $compute "model" $model -}}
{{- with .flag.tag }}{{ $_ := set $body "tags" . }}{{ end -}}
{{- toJson $body -}}

{{- $model := dict -}}
{{- with .flag.repository }}{{ $_ := set $model "repository" . }}{{ end -}}
{{- with .flag.framework }}{{ $_ := set $model "framework" . }}{{ end -}}
{{- with .flag.revision }}{{ $_ := set $model "revision" . }}{{ end -}}
{{- with .flag.task }}{{ $_ := set $model "task" . }}{{ end -}}
{{- with .flag.image }}{{ $_ := set $model "image" (mustFromJson .) }}{{ end -}}
{{- $scaling := dict -}}
{{- if ge (index .flag "min-replica") 0 }}{{ $_ := set $scaling "minReplica" (index .flag "min-replica") }}{{ end -}}
{{- if ge (index .flag "max-replica") 0 }}{{ $_ := set $scaling "maxReplica" (index .flag "max-replica") }}{{ end -}}
{{- if ge (index .flag "scale-to-zero-timeout") 0 }}{{ $_ := set $scaling "scaleToZeroTimeout" (index .flag "scale-to-zero-timeout") }}{{ end -}}
{{- $compute := dict -}}
{{- with .flag.accelerator }}{{ $_ := set $compute "accelerator" . }}{{ end -}}
{{- with index .flag "instance-type" }}{{ $_ := set $compute "instanceType" . }}{{ end -}}
{{- with index .flag "instance-size" }}{{ $_ := set $compute "instanceSize" . }}{{ end -}}
{{- if $scaling }}{{ $_ := set $compute "scaling" $scaling }}{{ end -}}
{{- $body := dict -}}
{{- if $model }}{{ $_ := set $body "model" $model }}{{ end -}}
{{- if $compute }}{{ $_ := set $body "compute" $compute }}{{ end -}}
{{- with .flag.type }}{{ $_ := set $body "type" . }}{{ end -}}
{{- with .flag.tag }}{{ $_ := set $body "tags" . }}{{ end -}}
{{- toJson $body -}}
